SELECT detail_id
FROM law_api_document_details
WHERE document_id = #{documentId}

SELECT d.document_id AS documentId, d.detail_id AS detailId, doc.target AS target, doc.title AS title, d.detail_title AS detailTitle, d.raw_json AS rawJson FROM law_api_document_details d JOIN law_api_documents doc ON doc.document_id = d.document_id WHERE doc.use_yn = 'Y' AND d.use_yn = 'Y' AND doc.target = #{target} AND d.document_id IN
#{documentId}
ORDER BY d.document_id
